// Every image is tracked by the visual-completion walk.
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";

const styles = stylex.create({
  base: { display: "block", objectFit: "cover", backgroundColor: colors.glimmer, maxWidth: "100%" },
  size: (width, height) => ({ width, height }),
  fill: { width: "100%", height: "100%" },
});

export default function UIImage({ src, width, height, alt = "", fill = false, xstyle, ...rest }) {
  return <img {...rest} src={src} alt={alt} width={fill ? undefined : width} height={fill ? undefined : height} decoding="async" data-visualcompletion="media-vc-image" {...stylex.props(styles.base, fill ? styles.fill : styles.size(width, height), xstyle)} />;
}
