import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";

const styles = stylex.create({
  base: { borderStyle: "none", height: 1, margin: 0, backgroundColor: colors.divider, flexShrink: 0 },
  inset: { marginInline: 16 },
  spaced: { marginBlock: 8 },
});

export default function UIDivider({ inset = false, spaced = false }) {
  return <hr role="separator" {...stylex.props(styles.base, inset && styles.inset, spaced && styles.spaced)} />;
}
