// Registers the element a ref lands on for impression logging.
import { useCallback, useRef } from "react";
import { trackImpression } from "ImpressionTracker";

export default function useImpression(id, kind, tracking = null) {
  const cleanup = useRef(null);
  return useCallback(
    (element) => {
      cleanup.current?.();
      cleanup.current = element ? trackImpression(element, { id, kind, tracking }) : null;
    },
    [id, kind, tracking],
  );
}
