// Logs an impression for each story, comment and sponsored unit, through
// one IntersectionObserver per threshold, as the reference does for its feed
// units. Registration happens on mount; deliveries land after the step.
import EventLogger from "EventLogger";

const observers = new Map();
const targets = new WeakMap();
const seen = new Set();

function observerFor(threshold) {
  let observer = observers.get(threshold);
  if (!observer) {
    observer = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        const info = targets.get(entry.target);
        if (!info || !entry.isIntersecting || seen.has(info.id)) {
          continue;
        }
        seen.add(info.id);
        EventLogger.log("impression", { id: info.id, kind: info.kind, ratio: entry.intersectionRatio, tracking: info.tracking });
      }
    }, { threshold });
    observers.set(threshold, observer);
  }
  return observer;
}

export function trackImpression(element, info, threshold = 0.5) {
  targets.set(element, info);
  const observer = observerFor(threshold);
  observer.observe(element);
  return () => {
    observer.unobserve(element);
    targets.delete(element);
  };
}
