import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { leftRailItemTokens } from "ComponentTokens.stylex";
import UIText from "UIText.react";
import UIIcon from "UIIcon.react";
import UIAvatar from "UIAvatar.react";
import UIImage from "UIImage.react";
import UILink from "UILink.react";
import UIDivider from "UIDivider.react";
import UIBadge from "UIBadge.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";

const styles = stylex.create({
  rail: { paddingTop: 16, paddingInline: 8, paddingBottom: 24 },
  item: { gap: 12, paddingInline: 8, minHeight: 52, borderRadius: leftRailItemTokens.radius },
  iconWell: { width: 36, height: 36, display: "flex", alignItems: "center", justifyContent: "center" },
  heading: { paddingInline: 8, paddingTop: 12, paddingBottom: 4 },
  shortcutImage: { borderRadius: 8 },
  footer: { paddingInline: 8, paddingTop: 12, gap: 4 },
  badge: { marginInlineStart: "auto" },
});

function RailItem({ href, label, icon = null, image = null, avatar = null, badgeCount = 0, testid }) {
  return (
    <UILink href={href} block label={label} testid={testid}>
      <UIRow xstyle={styles.item}>
        {avatar ? <UIAvatar src={avatar} size={36} /> : null}
        {image ? <UIImage src={image} width={36} height={36} xstyle={styles.shortcutImage} /> : null}
        {icon ? (
          <span {...stylex.props(styles.iconWell)}>
            <UIIcon name={icon} size={24} color="accent" />
          </span>
        ) : null}
        <UIText weight="medium" numberOfLines={1}>
          {label}
        </UIText>
        {badgeCount > 0 ? <UIBadge count={badgeCount} xstyle={styles.badge} /> : null}
      </UIRow>
    </UILink>
  );
}

export default function LeftRail({ rail }) {
  const data = useFragment(
    graphql`
      fragment LeftRail_rail on LeftRail {
        viewer_entry {
          id
          name
          url
          profile_picture(size: 36) {
            uri
          }
        }
        primary_items {
          key
          label
          icon_name
          url
          badge_count
        }
        shortcuts {
          id
          title
          url
          kind
          image {
            uri
          }
        }
        footer_links {
          label
          url
        }
      }
    `,
    rail,
  );
  return (
    <LoggingSurface name="left_rail">
      <UIColumn as="nav" xstyle={styles.rail}>
        {data.viewer_entry ? <RailItem href={data.viewer_entry.url} label={data.viewer_entry.name} avatar={data.viewer_entry.profile_picture?.uri} testid="left-rail-viewer" /> : null}
        {data.primary_items.map((item) => (
          <RailItem key={item.key} href={item.url} label={item.label} icon={item.icon_name} badgeCount={item.badge_count} />
        ))}
        <UIDivider spaced />
        <UIText type="headline4" color="secondary" xstyle={styles.heading}>
          Your shortcuts
        </UIText>
        {data.shortcuts.map((shortcut) => (
          <RailItem key={shortcut.id} href={shortcut.url} label={shortcut.title} image={shortcut.image?.uri} />
        ))}
        <UIRow wrap xstyle={styles.footer}>
          {data.footer_links.map((link, i) => (
            <UIText key={link.label} type="caption" color="secondary">
              {i > 0 ? "· " : ""}
              {link.label}
            </UIText>
          ))}
        </UIRow>
      </UIColumn>
    </LoggingSurface>
  );
}
