import * as stylex from "@stylexjs/stylex";
import { colors, type } from "BaseTokens.stylex";

const styles = stylex.create({
  base: { fontFamily: type.fontFamily, margin: 0, overflowWrap: "anywhere", minWidth: 0 },
  caption: { fontSize: type.captionSize, lineHeight: type.captionLineHeight },
  meta: { fontSize: type.metaSize, lineHeight: type.metaLineHeight },
  body: { fontSize: type.bodySize, lineHeight: type.bodyLineHeight },
  bodyLarge: { fontSize: type.bodyLargeSize, lineHeight: type.bodyLargeLineHeight },
  headline4: { fontSize: type.headline4Size, lineHeight: type.headline4LineHeight, fontWeight: type.weightSemibold },
  headline3: { fontSize: type.headline3Size, lineHeight: type.headline3LineHeight, fontWeight: type.weightBold },
  headline2: { fontSize: type.headline2Size, lineHeight: type.headline2LineHeight, fontWeight: type.weightBold },
  headline1: { fontSize: type.headline1Size, lineHeight: type.headline1LineHeight, fontWeight: type.weightBold },
  primary: { color: colors.primaryText },
  secondary: { color: colors.secondaryText },
  tertiary: { color: colors.tertiaryText },
  accent: { color: colors.accentText },
  link: { color: colors.blueLink },
  onAccent: { color: colors.onAccent },
  disabled: { color: colors.disabledText },
  medium: { fontWeight: type.weightMedium },
  semibold: { fontWeight: type.weightSemibold },
  bold: { fontWeight: type.weightBold },
  truncate: { overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" },
  clamp: (lines) => ({ display: "-webkit-box", WebkitBoxOrient: "vertical", WebkitLineClamp: lines, overflow: "hidden" }),
  block: { display: "block" },
});

export default function UIText({ as: Tag = "span", type: textType = "body", color = "primary", weight = null, numberOfLines = 0, block = false, xstyle, children, ...rest }) {
  return (
    <Tag
      {...rest}
      {...stylex.props(
        styles.base,
        styles[textType],
        styles[color],
        weight !== null && styles[weight],
        numberOfLines === 1 && styles.truncate,
        numberOfLines > 1 && styles.clamp(numberOfLines),
        block && styles.block,
        xstyle,
      )}
    >
      {children}
    </Tag>
  );
}
